CREATE TABLE IF NOT EXISTS public.opportunity_sheet_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, spreadsheet_id text NOT NULL, status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','failed')), row_count integer NOT NULL DEFAULT 0 CHECK(row_count>=0), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, error_message text);
GRANT SELECT ON public.opportunity_sheet_runs TO authenticated;
GRANT ALL ON public.opportunity_sheet_runs TO service_role;
ALTER TABLE public.opportunity_sheet_runs ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='opportunity_sheet_runs' AND policyname='admin_read_sheet_runs') THEN CREATE POLICY admin_read_sheet_runs ON public.opportunity_sheet_runs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') AND public.has_permission('opportunities.read','view')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.opportunity_export_page(_search text DEFAULT '',_stage text DEFAULT '',_source text DEFAULT '',_owner text DEFAULT '',_board boolean DEFAULT true,_limit integer DEFAULT 500,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH filtered AS (SELECT o.id,o.party_id,o.stage::text AS stage,o.source::text AS source,o.owner_user_id,o.next_action,o.next_action_at,o.created_at,p.name_ar AS customer_name,p.tenant_code,(SELECT coalesce(pr.display_name,'بدون اسم') FROM public.profiles pr WHERE pr.user_id=o.owner_user_id LIMIT 1) AS owner_name FROM public.opportunities o LEFT JOIN public.parties_crm p ON p.id=o.party_id WHERE public.has_permission('opportunities.read','view') AND (NOT _board OR o.outcome IS NULL) AND (_stage='' OR o.stage::text=_stage) AND (_source='' OR o.source::text=_source) AND (_owner='' OR (_owner='none' AND o.owner_user_id IS NULL) OR o.owner_user_id::text=_owner) AND (_search='' OR concat_ws(' ',p.name_ar,p.tenant_code,o.id::text) ILIKE '%'||left(_search,100)||'%')), paged AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(paged)) FROM paged),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)); $$;
REVOKE ALL ON FUNCTION public.opportunity_export_page(text,text,text,text,boolean,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.opportunity_export_page(text,text,text,text,boolean,integer,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.start_opportunity_sheet_sync() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.opportunity_sheet_runs; sid text; BEGIN
IF NOT public.has_role(auth.uid(),'admin') OR NOT public.has_permission('opportunities.read','view') THEN RAISE EXCEPTION 'تحديث شيت الفرص للأدمن فقط'; END IF;
PERFORM pg_advisory_xact_lock(hashtext('opportunity_sheet_sync'));
IF EXISTS(SELECT 1 FROM public.opportunity_sheet_runs WHERE status='running' AND started_at>now()-interval '15 minutes') THEN RAISE EXCEPTION 'يوجد تحديث للشيت قيد التنفيذ'; END IF;
SELECT buildings_sheet_id INTO sid FROM public.app_settings WHERE id=1; IF coalesce(sid,'')='' THEN RAISE EXCEPTION 'الشيت الحالي غير محدد'; END IF;
INSERT INTO public.opportunity_sheet_runs(actor_id,spreadsheet_id) VALUES(auth.uid(),sid) RETURNING * INTO r;
PERFORM public._safety_audit('OPPORTUNITIES_SHEET_STARTED','opportunity_sheet_runs',r.id::text,NULL,to_jsonb(r),'تحديث تبويب الفرص من المنصة للشيت فقط'); RETURN to_jsonb(r); END $$;
CREATE OR REPLACE FUNCTION public.finish_opportunity_sheet_sync(_id uuid,_success boolean,_count integer,_error text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.opportunity_sheet_runs; a public.opportunity_sheet_runs; BEGIN
IF NOT public.has_role(auth.uid(),'admin') OR NOT public.has_permission('opportunities.read','view') THEN RAISE EXCEPTION 'تحديث شيت الفرص للأدمن فقط'; END IF;
SELECT * INTO b FROM public.opportunity_sheet_runs WHERE id=_id AND actor_id=auth.uid() FOR UPDATE; IF b.id IS NULL OR b.status<>'running' THEN RAISE EXCEPTION 'عملية تحديث غير صالحة'; END IF;
IF _count<0 THEN RAISE EXCEPTION 'عدد غير صالح'; END IF;
UPDATE public.opportunity_sheet_runs SET status=CASE WHEN _success THEN 'succeeded' ELSE 'failed' END,row_count=_count,completed_at=now(),error_message=CASE WHEN _success THEN NULL ELSE left(_error,2000) END WHERE id=_id RETURNING * INTO a;
PERFORM public._safety_audit('OPPORTUNITIES_SHEET_COMPLETED','opportunity_sheet_runs',a.id::text,to_jsonb(b),to_jsonb(a),'تسجيل نتيجة تحديث تبويب الفرص'); END $$;
REVOKE ALL ON FUNCTION public.start_opportunity_sheet_sync(),public.finish_opportunity_sheet_sync(uuid,boolean,integer,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.start_opportunity_sheet_sync(),public.finish_opportunity_sheet_sync(uuid,boolean,integer,text) TO authenticated;
SELECT to_regclass('public.opportunity_sheet_runs') IS NOT NULL AS table_ready,to_regprocedure('public.opportunity_export_page(text,text,text,text,boolean,integer,integer)') IS NOT NULL AS export_ready,to_regprocedure('public.start_opportunity_sheet_sync()') IS NOT NULL AS sync_ready;